def sum_to(n):
    total = 0
    for k in range(1, n + 1):
        total += k
    return total


def depth(n, d=1):
    if n < 2:
        return d
    return max(depth(n - 1, d + 1), depth(n - 2, d + 1))

def levels(node):
    deepest = 0
    for child in node["children"]:
        deepest = max(deepest, levels(child))
    return 1 + deepest

